async function readInbox(path,current){const controller=new AbortController();let rejectDeadline;const expired=new Promise((_,reject)=>rejectDeadline=reject);const slow=setTimeout(()=>{if(current())$('clinicCareStatus').textContent='일부 업무 영역 연결 확인 중… 조회가 완료된 업무는 바로 사용할 수 있습니다.';},6000),deadline=setTimeout(()=>{controller.abort();rejectDeadline(Error('업무 조회 시간 초과 · 업무 새로고침으로 다시 확인해주세요.'));},20000);try{return await Promise.race([api(path,{signal:controller.signal}),expired]);}finally{clearTimeout(slow);clearTimeout(deadline);}}
