 await Promise.allSettled(reads.map(async({type,state})=>{const current=()=>auth===scope()&&epoch===generation&&inboxRegions[type]===state;try{const result=await readInbox(paths[type],current);if(!current())return;state.items=inboxTasks(type,result,auth);state.state='ready';}catch(e){if(!current())return;state.state='failed';}if(current())render();}));
