 const start=new Date(startDate+'T00:00:00Z');if(!/^20\d{2}-\d{2}-\d{2}$/.test(startDate)||!Number.isFinite(start.getTime())||start.toISOString().slice(0,10)!==startDate)throw Object.assign(Error('관리 시작일을 확인해주세요.'),{field:'start'});
