 function writeTimes(times){if(times.length>6){onError('투약 시간은 최대 6개까지 등록할 수 있습니다.');return false;}setMedicationRowTimes(card(),times);changed();return true;}
 function add(time){if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(time||'')){onError('추가할 투약 시간을 선택해주세요.');return;}const times=parseMedTimes(field('times').value);if(times.includes(time)){onError(time+'은 이미 등록된 시간입니다.');return;}if(writeTimes([...times,time]))card().querySelector('[data-med-time-input]').value='';}
