function medicationStoredDraftValid(saved,now=Date.now()){return !!saved&&!!saved.m&&!Array.isArray(saved.m)&&typeof saved.m==='object'&&typeof saved.start==='string'&&saved.expiresAt>now&&saved.expiresAt<=now+1800000;}
function clearStoredMedicationDrafts(){try{for(const key of Object.keys(sessionStorage))if(key.startsWith('carestep-med-draft:'))sessionStorage.removeItem(key);}catch{}}
